// allowedEventFields is the exact set of members each event object may
// carry; anything else is an unknown field.
var allowedEventFields = map[string]struct{}{
	"id":       {},
	"service":  {},
	"severity": {},
	"message":  {},
	"at":       {},
	"labels":   {},
}

