1	package metrics
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"time"
9	
10		"github.com/cocosolocoder/signalroom/internal/events"
11	)
12	
13	// sampleDTO is the on-disk representation of a normalized sample. Timestamps
14	// use RFC3339Nano; Labels is omitted entirely when a sample has none.
15	type sampleDTO struct {
16		ID      string            `json:"id"`
17		Service string            `json:"service"`
18		Name    string            `json:"name"`
19		At      time.Time         `json:"at"`
20		Value   float64           `json:"value"`
21		Labels  map[string]string `json:"labels,omitempty"`
22	}
23	
24	// allowedSampleFields is the exact set of members one sample may carry.
25	var allowedSampleFields = map[string]struct{}{
26		"id":      {},
27		"service": {},
28		"name":    {},
29		"at":      {},
30		"value":   {},
31		"labels":  {},
32	}
33	
34	// rawSample keeps the labels member unexamined so the same strict,
35	// duplicate-rejecting object decoder events use can validate it.
36	type rawSample struct {
37		id      string
38		service string
39		name    string
40		at      time.Time
41		value   float64
42		labels  map[string]string
43	}
44	
45	// MarshalBatch encodes normalized samples as a JSON array.
46	func MarshalBatch(batch []Sample) ([]byte, error) {
47		dtos := make([]sampleDTO, len(batch))
48		for i, sample := range batch {
49			dtos[i] = sampleDTO{
50				ID:      sample.ID,
51				Service: sample.Service,
52				Name:    sample.Name,
53				At:      sample.At,
54				Value:   sample.Value,
55				Labels:  sample.Labels,
56			}
57		}
58		return json.Marshal(dtos)
59	}
60	
61	// DecodeBatch strictly decodes a JSON array of samples. Unknown fields,
62	// duplicate JSON members (at the sample level or inside labels), syntax
63	// errors, malformed timestamps, non-numeric or non-finite values, malformed
64	// labels, and trailing data are all rejected; callers remain responsible for
65	// the empty-array check and content validation.
66	func DecodeBatch(data []byte) ([]Sample, error) {
67		dec := json.NewDecoder(bytes.NewReader(data))
68		open, err := dec.Token()
69		if err != nil {
70			return nil, fmt.Errorf("decode samples array: %w", err)
71		}
72		if delim, ok := open.(json.Delim); !ok || delim != '[' {
73			return nil, fmt.Errorf("decode samples array: must be an array")
74		}
75	
76		var batch []Sample
77		for dec.More() {
78			raw, err := decodeSample(dec)
79			if err != nil {
80				return nil, err
81			}
82			batch = append(batch, Sample{
83				ID:      raw.id,
84				Service: raw.service,
85				Name:    raw.name,
86				At:      raw.at,
87				Value:   raw.value,
88				Labels:  raw.labels,
89			})
90		}
91		if _, err := dec.Token(); err != nil { // closing ']'
92			return nil, fmt.Errorf("decode samples array: %w", err)
93		}
94		var extra json.RawMessage
95		if err := dec.Decode(&extra); err != io.EOF {
96			if err == nil {
97				return nil, fmt.Errorf("decode samples array: unexpected trailing data")
98			}
99			return nil, fmt.Errorf("decode samples array: %w", err)
100		}
101		return batch, nil
102	}
103	
104	// decodeSample reads exactly one sample object, rejecting unknown and
105	// duplicate members rather than letting a struct decode silently keep the
106	// last value.
107	func decodeSample(dec *json.Decoder) (rawSample, error) {
108		open, err := dec.Token()
109		if err != nil {
110			return rawSample{}, fmt.Errorf("decode sample: %w", err)
111		}
112		if delim, ok := open.(json.Delim); !ok || delim != '{' {
113			return rawSample{}, fmt.Errorf("decode sample: each sample must be an object")
114		}
115	
116		var raw rawSample
117		var labelsRaw json.RawMessage
118		seen := make(map[string]struct{})
119		for dec.More() {
120			keyToken, err := dec.Token()
121			if err != nil {
122				return rawSample{}, fmt.Errorf("decode sample: %w", err)
123			}
124			key, ok := keyToken.(string)
125			if !ok {
126				return rawSample{}, fmt.Errorf("decode sample: field names must be strings")
127			}
128			if _, known := allowedSampleFields[key]; !known {
129				return rawSample{}, fmt.Errorf("decode sample: unknown field %q", key)
130			}
131			if _, dup := seen[key]; dup {
132				return rawSample{}, fmt.Errorf("decode sample: duplicate field %q", key)
133			}
134			seen[key] = struct{}{}
135	
136			switch key {
137			case "id", "service", "name":
138				var value string
139				if err := dec.Decode(&value); err != nil {
140					return rawSample{}, fmt.Errorf("decode sample: %s must be a string", key)
141				}
142				switch key {
143				case "id":
144					raw.id = value
145				case "service":
146					raw.service = value
147				case "name":
148					raw.name = value
149				}
150			case "at":
151				var at time.Time
152				if err := dec.Decode(&at); err != nil {
153					return rawSample{}, fmt.Errorf("decode sample: at must be an RFC3339Nano timestamp")
154				}
155				raw.at = at
156			case "value":
157				// Decode the raw token first: json.Number has an underlying string
158				// type, so a quoted "1" would otherwise decode into it. Require
159				// the token to literally be a JSON number before parsing.
160				var token json.RawMessage
161				if err := dec.Decode(&token); err != nil {
162					return rawSample{}, fmt.Errorf("decode sample: value must be a JSON number")
163				}
164				number := bytes.TrimSpace(token)
165				if !isJSONNumber(number) {
166					return rawSample{}, fmt.Errorf("decode sample: value must be a non-negative, finite JSON number")
167				}
168				value, err := json.Number(number).Float64()
169				if err != nil || !finiteNonNegative(value) {
170					return rawSample{}, fmt.Errorf("decode sample: value must be a non-negative, finite JSON number")
171				}
172				raw.value = value
173			case "labels":
174				if err := dec.Decode(&labelsRaw); err != nil {
175					return rawSample{}, fmt.Errorf("decode sample: labels must be an object")
176				}
177			}
178		}
179		if _, err := dec.Token(); err != nil { // closing '}'
180			return rawSample{}, fmt.Errorf("decode sample: %w", err)
181		}
182	
183		labels, err := events.DecodeLabelsObject(labelsRaw)
184		if err != nil {
185			return rawSample{}, err
186		}
187		// value has no useful zero value, so an absent member is an error rather
188		// than a silent 0; id/service/name/at are caught by later normalization.
189		if _, ok := seen["value"]; !ok {
190			return rawSample{}, fmt.Errorf("decode sample: value is required")
191		}
192		raw.labels = labels
193		return raw, nil
194	}
195	
196	// isJSONNumber validates the strict JSON number grammar, so a quoted string,
197	// NaN, or Infinity never reach the float parser.
198	func isJSONNumber(b []byte) bool {
199		i := 0
200		if i < len(b) && b[i] == '-' {
201			i++
202		}
203		if i >= len(b) {
204			return false
205		}
206		if b[i] == '0' {
207			i++
208		} else if b[i] >= '1' && b[i] <= '9' {
209			i++
210			for i < len(b) && b[i] >= '0' && b[i] <= '9' {
211				i++
212			}
213		} else {
214			return false
215		}
216		if i < len(b) && b[i] == '.' {
217			i++
218			if i >= len(b) || b[i] < '0' || b[i] > '9' {
219				return false
220			}
221			for i < len(b) && b[i] >= '0' && b[i] <= '9' {
222				i++
223			}
224		}
225		if i < len(b) && (b[i] == 'e' || b[i] == 'E') {
226			i++
227			if i < len(b) && (b[i] == '+' || b[i] == '-') {
228				i++
229			}
230			if i >= len(b) || b[i] < '0' || b[i] > '9' {
231				return false
232			}
233			for i < len(b) && b[i] >= '0' && b[i] <= '9' {
234				i++
235			}
236		}
237		return i == len(b)
238	}
