		sample(`"labels":{"env":"prod","env":"dev"}`),                              // differing label values still dup
		sample(`"labels":{"env":"prod","` + u("0065", "nv") + `":null}`),           // escaped label name == env
		sample(`"labels":null,"labels":{"env":"prod"}`),                            // labels member twice
