			ID:      raw.id,
			Service: raw.service,
			Name:    raw.name,
			At:      raw.at,
			Value:   raw.value,
			Labels:  raw.labels,
		})
		return nil
	})
	if err != nil {
		return nil, err
	}
	return batch, nil
}

